UPDATE "work_areas"
SET
  "latitude" = CASE "id"
    WHEN '11111111-1111-4111-8111-111111111111' THEN -34.92145
    WHEN '33333333-3333-4333-8333-333333333332' THEN -34.90872
    WHEN '33333333-3333-4333-8333-333333333334' THEN -34.93418
    WHEN '33333333-3333-4333-8333-333333333333' THEN -34.89567
    WHEN '33333333-3333-4333-8333-333333333331' THEN -34.94621
  END,
  "longitude" = CASE "id"
    WHEN '11111111-1111-4111-8111-111111111111' THEN -57.95453
    WHEN '33333333-3333-4333-8333-333333333332' THEN -57.93841
    WHEN '33333333-3333-4333-8333-333333333334' THEN -57.97126
    WHEN '33333333-3333-4333-8333-333333333333' THEN -57.96084
    WHEN '33333333-3333-4333-8333-333333333331' THEN -57.94273
  END,
