WHERE "id" IN (
  '11111111-1111-4111-8111-111111111111',
  '33333333-3333-4333-8333-333333333332',
  '33333333-3333-4333-8333-333333333334',
  '33333333-3333-4333-8333-333333333333',
  '33333333-3333-4333-8333-333333333331'
